//! Bit-exact parity with the original DLL's CvRandom (fixture generated by
//! tools/parity/build.sh from the C++ source).

use ffh_core::rng::Rng;

#[test]
fn cvrandom_matches_cpp() {
    let fixture = include_str!("fixtures/cvrandom.txt");
    let nums: [u16; 7] = [0, 1, 2, 7, 100, 1000, 65535];
    for line in fixture.lines() {
        let (head, rest) = line.split_once(':').unwrap();
        let seed: u32 = head.trim_start_matches("seed ").parse().unwrap();
        let toks: Vec<&str> = rest.split_whitespace().collect();
        let mut r = Rng::new(seed);
        for i in 0..40 {
            let expect: u16 = toks[i].parse().unwrap();
            assert_eq!(r.get(nums[i % 7], ""), expect, "seed {seed} draw {i}");
        }
        let f: f32 = toks[40].trim_start_matches("f=").parse().unwrap();
        assert!((r.get_float() - f).abs() < 1e-6, "seed {seed} float");
        let end: u32 = toks[41].trim_start_matches("end=").parse().unwrap();
        assert_eq!(r.seed(), end, "seed {seed} end state");
    }
}
